use verus::prelude::*;

verus! {
    /// For each element of `arr`, we insert `elem` immediately before it,
    /// so the output has length `arr.len() * 2`, and for all 0 ≤ i < arr.len():
    ///   result[2*i]   == elem
    ///   result[2*i+1] == arr[i]
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> Vec<i32>
        ensures
            |result: &Vec<i32>| result.len() == arr.len() * 2
                          && (forall|i: usize| i < arr.len() ==>
                                 result[2*i] == elem &&
                                 result[2*i + 1] == arr[i])
    {
        let mut result = Vec::with_capacity(arr.len() * 2);
        // As we walk through `arr`, we keep the following loop‐invariant:
        //   at the start of each iteration, result.len() == 2 * k
        //   and for all j < k, result[2*j] == elem && result[2*j+1] == arr[j]
        for &value in arr.iter() {
            // compute how many pairs we have already established
            let before_len = result.len();
            let k = before_len / 2;
            result.push(elem);
            result.push(value);
            // now we have one more correct pair, so for all j <= k:
            assert(forall|j: usize| j <= k ==>
                      result[2*j]     == elem &&
                      result[2*j + 1] == arr[j]);
        }
        result
    }
}

